import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { execFileSync } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";
import Database from "better-sqlite3";
import { sourceIdentity, hash, workflowFixture, type LegacySeed, type WorkflowFixture } from "./w01-performance-fixture";
import { declareVisibility,type VisibilityReceipt } from "./w02-measurement";
import { boundedLaunch, boundedPair, boundedFetch, readBoundedText } from "./w01-runtime";
export const integratedW01="e5bf6da0e22a64b40fc5817fb1d3a4d237bdb168";
export type W02Prepared={visibility:VisibilityReceipt[];samples:{id:string;label:string;operation:string;repetition:number;index:number;warmup:boolean}[];root:string;sources:Record<"base"|"head",string>;identities:Record<string,ReturnType<typeof sourceIdentity>>;seeds:Record<string,LegacySeed>;seedDirs:Record<string,string>;scenarioDir:string;workflow:WorkflowFixture;diamond:string[];files:Record<string,string>;schemas:Record<string,unknown>};
export function tree(root:string){const result:Record<string,string>={};function walk(dir:string){for(const name of readdirSync(dir).sort()){const full=join(dir,name);if(statSync(full).isDirectory())walk(full);else result[relative(root,full)]=hash(readFileSync(full));}}walk(root);return result;}
export const requiredW02Helpers=["tests/performance/w02.ts","tests/fixtures/w02-measurement.ts","tests/fixtures/w02-preparation.ts","tests/fixtures/w02-operations.ts","tests/fixtures/w02-visibility.ts","tests/unit/w02-measurement.test.ts","tests/e2e/w02-measurement-controls.spec.ts"];
export function helperHashes(root:string){return Object.fromEntries(requiredW02Helpers.map(p=>{assert(existsSync(join(root,p)),`required helper missing: ${p}`);return [p,hash(readFileSync(join(root,p)))];}));}
export function w02Identity(source:string){return {...sourceIdentity(source),w02DriverSource:process.cwd(),w02Helpers:helperHashes(process.cwd())};}
export function schema(dir:string){const db=new Database(join(dir,"agentflow.sqlite"),{readonly:true});try{return {migrations:db.prepare("SELECT * FROM migration_history ORDER BY id").all(),counts:Object.fromEntries(["tasks","runs","run_events"].map(t=>[t,(db.prepare(`SELECT count(*) n FROM ${t}`).get() as {n:number}).n])),integrity:db.pragma("integrity_check"),foreignKeys:db.pragma("foreign_key_check")};}finally{db.close();}}
export async function prepareW02(root:string,base:string,head:string,operations:Record<"base"|"head",string[]>){assert(isAbsolute(root)&&!existsSync(root),"fresh private absolute preparation root required");assert.equal(realpathSync(base),base);assert.equal(realpathSync(head),head);assert.equal(execFileSync("git",["rev-parse","HEAD"],{cwd:base,encoding:"utf8"}).trim(),integratedW01);mkdirSync(root,{mode:0o700});const samples=(["base","head"] as const).flatMap(label=>[1,2,3].flatMap(repetition=>operations[label].flatMap(operation=>Array.from({length:110},(_,index)=>({id:`${label}:${repetition}:${operation}:${index}`,label,operation,repetition,index,warmup:index<10})))));const prepared={samples,root,sources:{base,head},identities:{},seeds:{},seedDirs:{},schemas:{}} as W02Prepared;
 for(const label of ["base","head"] as const){const source=prepared.sources[label],dir=join(root,label+"-seed"),output=join(root,label+"-seed.json");mkdirSync(dir,{mode:0o700});execFileSync(process.execPath,["--import","tsx",join(head,"tests/fixtures/p06-baseline-seed.ts"),join(source,"tests/fixtures/p06-performance.ts"),dir,JSON.stringify({tasks:1000,events:10000,producers:10}),output],{cwd:source,env:process.env,timeout:60000});prepared.seedDirs[label]=dir;prepared.seeds[label]=JSON.parse(readFileSync(output,"utf8"));prepared.identities[label]=w02Identity(source);prepared.schemas[label]=schema(dir);}
 const headSeed=prepared.seeds.head;prepared.scenarioDir=join(root,"head-scenario-seed");cpSync(prepared.seedDirs.head,prepared.scenarioDir,{recursive:true});prepared.workflow=await workflowFixture(prepared.scenarioDir,headSeed);prepared.diamond=headSeed.tasks.slice(20,24);const server=await boundedLaunch({dir:prepared.scenarioDir,cwd:head});try{const session=await boundedPair(server);for(const [index,prerequisiteIds] of [[0,[]],[1,[prepared.diamond[0]]],[2,[prepared.diamond[0]]],[3,prepared.diamond.slice(1,3)]] as [number,string[]][]){const response=await boundedFetch(server.url+`/api/v1/tasks/${prepared.diamond[index]}/dependencies`,{method:"PUT",headers:{Cookie:session,Origin:server.url,"Content-Type":"application/json","Idempotency-Key":randomUUID()},body:JSON.stringify({expectedVersion:1,prerequisiteIds})});const text=await readBoundedText(response);assert.equal(response.status,200,text);}const target=prepared.diamond[3];const detail=await boundedFetch(server.url+`/api/v1/tasks/${target}`,{headers:{Authorization:"Bearer "+server.credentials().reporterToken}});const task=JSON.parse(await readBoundedText(detail)).data.task;const policy=await boundedFetch(server.url+`/api/v1/tasks/${target}/review-policy`,{method:"PATCH",headers:{Cookie:session,Origin:server.url,"Content-Type":"application/json","Idempotency-Key":randomUUID()},body:JSON.stringify({expectedVersion:task.version,reviewRequired:true,verificationRequired:true})});assert.equal(policy.status,200,await readBoundedText(policy));}finally{await server.stop();}
 prepared.visibility=declareVisibility({projectId:headSeed.projectId,workflowId:prepared.workflow.workflowId,revisionId:prepared.workflow.revisionId,nodeId:prepared.workflow.nodeIds[23],taskId:prepared.diamond[3]});prepared.schemas.scenario=schema(prepared.scenarioDir);prepared.files=Object.fromEntries(Object.entries({...prepared.seedDirs,scenario:prepared.scenarioDir}).flatMap(([label,dir])=>Object.entries(tree(dir)).map(([path,digest])=>[label+"/"+path,digest])));writeFileSync(join(root,"prepared.json"),JSON.stringify(prepared,null,2),{mode:0o600,flag:"wx"});return prepared;}
export function readW02(root:string){const p=JSON.parse(readFileSync(join(root,"prepared.json"),"utf8")) as W02Prepared;assert.equal(p.sources.head,process.cwd());for(const label of ["base","head"] as const){assert.deepEqual(w02Identity(p.sources[label]),p.identities[label],"frozen source/runtime/addon/build/helper identities changed");assert.deepEqual(tree(p.seedDirs[label]),Object.fromEntries(Object.entries(p.files).filter(([path])=>path.startsWith(label+"/")).map(([path,digest])=>[path.slice(label.length+1),digest])),"frozen fixture changed");}assert.deepEqual(tree(p.scenarioDir),Object.fromEntries(Object.entries(p.files).filter(([path])=>path.startsWith("scenario/")).map(([path,digest])=>[path.slice(9),digest])));return p;}
export function copySeed(p:W02Prepared,label:string,destination:string){assert(!existsSync(destination));cpSync(label==="scenario"?p.scenarioDir:p.seedDirs[label],destination,{recursive:true});return destination;}
